BEGIN TRANSACTION;
IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20261006215114_TechnicalManualReadingEdition'
)
BEGIN
    IF EXISTS (SELECT * FROM [sys].[identity_columns] WHERE [name] IN (N'Id', N'Format', N'ItemsJson', N'Module', N'Position', N'PublicationStatus', N'Text', N'Title', N'Version') AND [object_id] = OBJECT_ID(N'[content].[ReadingSetVersions]'))
        SET IDENTITY_INSERT [content].[ReadingSetVersions] ON;
    EXEC(N'INSERT INTO [content].[ReadingSetVersions] ([Id], [Format], [ItemsJson], [Module], [Position], [PublicationStatus], [Text], [Title], [Version])
    VALUES (''d3200000-0000-4000-8000-000000000001'', N''article'', N''[{"Id":1,"Prompt":"What is the passage mainly about?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Why rural areas need paved roads"},{"Id":"B","Text":"How trees cool cities and what supports their success"},{"Id":"C","Text":"Why cities should stop planting trees"},{"Id":"D","Text":"How to measure the age of a tree"}],"Answer":"B","Explanation":"Metin so\u011Futma mekanizmalar\u0131n\u0131, k\u0131s\u0131tlar\u0131 ve uzun vadeli dikim tasar\u0131m\u0131n\u0131 birle\u015Ftiriyor."},{"Id":2,"Prompt":"How does evaporation help cool the air?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It prevents all rainfall"},{"Id":"B","Text":"It releases stored solar energy"},{"Id":"C","Text":"It takes heat from the air"},{"Id":"D","Text":"It increases road temperature"}],"Answer":"C","Explanation":"\u0130lk paragraf buharla\u015Fan suyun \u00E7evredeki havadan \u0131s\u0131 ald\u0131\u011F\u0131n\u0131 belirtiyor."},{"Id":3,"Prompt":"The word \u0027constraints\u0027 is closest in meaning to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"celebrations"},{"Id":"B","Text":"measurements"},{"Id":"C","Text":"predictions"},{"Id":"D","Text":"limitations"}],"Answer":"D","Explanation":"Su gereksinimi ve iklim gibi ba\u015Far\u0131y\u0131 s\u0131n\u0131rlayan ko\u015Fullara g\u00F6nderme yap\u0131l\u0131yor."},{"Id":4,"Prompt":"Why does the author mention permeable paving?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To give an example of supporting tree survival"},{"Id":"B","Text":"To argue that shade is unnecessary"},{"Id":"C","Text":"To describe a rural farming method"},{"Id":"D","Text":"To show that roots should remain dry"}],"Answer":"A","Explanation":"Ge\u00E7irgen y\u00FCzey, a\u011Fa\u00E7lar\u0131 \u00E7evre sistemiyle birlikte planlaman\u0131n \u00F6rne\u011Fi."},{"Id":5,"Prompt":"What can be inferred about counting newly planted trees?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It always measures cooling accurately"},{"Id":"B","Text":"It is sufficient for planning"},{"Id":"C","Text":"It does not alone show long-term benefits"},{"Id":"D","Text":"It proves that trees will survive"}],"Answer":"C","Explanation":"Son paragraf say\u0131dan \u00E7ok ya\u015Fama ko\u015Fullar\u0131n\u0131n \u00F6nemli oldu\u011Funu vurguluyor."}]'', N''academic-passage'', 1, 2, CONCAT(CAST(N''Cities are often warmer than nearby rural areas because roads and buildings absorb solar energy and release it slowly. Trees can reduce this local warming in two ways. Their leaves shade surfaces, preventing some energy from reaching the ground. Trees also release water through their leaves; as this water evaporates, it takes heat from the surrounding air.'' AS nvarchar(max)), nchar(10), nchar(10), N''The benefits are unevenly distributed. A single tree beside a wide road provides less continuous shade than a connected row of trees. Moreover, a species that grows quickly may require more water than the local climate can supply. Planting without considering these constraints can lead to trees dying before they provide substantial shade.'', nchar(10), nchar(10), N''For this reason, some urban planners combine tree planting with changes to the surfaces beneath them. Permeable paving allows rainfall to reach roots instead of running directly into drains. Such planning treats trees as part of a larger system. The aim is not merely to increase the number planted, but to create conditions in which they can survive and cool streets for decades.''), N''Urban trees and local temperatures'', 2),
    (''d3200000-0000-4000-8000-000000000002'', N''article'', N''[{"Id":1,"Prompt":"What distinction is central to the passage?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Printed versus digital notes"},{"Id":"B","Text":"Familiarity versus unaided recall"},{"Id":"C","Text":"Morning versus evening study"},{"Id":"D","Text":"Science versus history lessons"}],"Answer":"B","Explanation":"\u0130lk paragraf tan\u0131d\u0131kl\u0131k hissi ile yard\u0131ms\u0131z hat\u0131rlaman\u0131n farkl\u0131l\u0131\u011F\u0131n\u0131 kuruyor."},{"Id":2,"Prompt":"Why should learners check answers after retrieval?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To avoid all future effort"},{"Id":"B","Text":"To memorize page numbers"},{"Id":"C","Text":"To identify and correct gaps"},{"Id":"D","Text":"To make sessions longer"}],"Answer":"C","Explanation":"Yan\u0131t\u0131 kaynakla kar\u015F\u0131la\u015Ft\u0131rma, eksikleri ve yanl\u0131\u015Flar\u0131 belirler."},{"Id":3,"Prompt":"What does \u0027accessible\u0027 mean in the final paragraph?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Available to recall"},{"Id":"B","Text":"Printed in large type"},{"Id":"C","Text":"Free to purchase"},{"Id":"D","Text":"Located nearby"}],"Answer":"A","Explanation":"Bilginin zaman ge\u00E7se de hat\u0131rlanabilir olmas\u0131 anlat\u0131l\u0131yor."},{"Id":4,"Prompt":"What can be inferred about an easy study session?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It must involve retrieval"},{"Id":"B","Text":"It guarantees long-term learning"},{"Id":"C","Text":"It requires no feedback"},{"Id":"D","Text":"It may give a misleading impression of learning"}],"Answer":"D","Explanation":"Kolayl\u0131k ve tan\u0131d\u0131kl\u0131k kal\u0131c\u0131 \u00F6\u011Frenmeyi tek ba\u015F\u0131na kan\u0131tlam\u0131yor."},{"Id":5,"Prompt":"How is the second paragraph organized?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"A historical event followed by dates"},{"Id":"B","Text":"A benefit followed by a condition for its success"},{"Id":"C","Text":"Two unrelated definitions"},{"Id":"D","Text":"A list of examination rules"}],"Answer":"B","Explanation":"Eksikleri g\u00F6rme yarar\u0131 anlat\u0131l\u0131p do\u011Fru geri bildirim ko\u015Fulu ekleniyor."}]'', N''academic-passage'', 2, 2, CONCAT(CAST(N''Students often prepare for an examination by reading their notes repeatedly. This can make the material feel familiar, but familiarity is not the same as being able to recall an idea without help. An alternative approach asks students to close their notes and attempt to explain what they remember. This process is known as retrieval practice.'' AS nvarchar(max)), nchar(10), nchar(10), N''Retrieval can be useful even when the first attempt is incomplete. After answering, a learner checks the original material and identifies gaps. The comparison provides a clearer guide for further study than the general feeling that a page looks familiar. However, feedback matters: repeatedly producing an incorrect answer without checking it may strengthen the error rather than correct it.'', nchar(10), nchar(10), N''Spacing these attempts over several days adds another challenge. Some forgetting occurs between sessions, so recall requires effort again. Although this can feel less comfortable than immediate repetition, it helps reveal whether knowledge remains accessible over time. Effective study therefore involves both attempting to retrieve information and using reliable feedback to refine it, rather than judging success solely by how easy a study session feels.''), N''When retrieval improves learning'', 2),
    (''d3200000-0000-4000-8000-000000000003'', N''article'', N''[{"Id":1,"Prompt":"What is the main idea?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Gold is always more informative than pottery"},{"Id":"B","Text":"Chemical tests eliminate uncertainty"},{"Id":"C","Text":"Pottery and its context together reveal past activities"},{"Id":"D","Text":"Broken objects should be discarded"}],"Answer":"C","Explanation":"Hem malzeme hem buluntu ba\u011Flam\u0131 ge\u00E7mi\u015F ya\u015Fam hakk\u0131nda kan\u0131t sunuyor."},{"Id":2,"Prompt":"What might chemical analysis reveal?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"The name of the pot\u0027s owner"},{"Id":"B","Text":"Food or drink residues"},{"Id":"C","Text":"The exact date of every scratch"},{"Id":"D","Text":"The value of gold"}],"Answer":"B","Explanation":"\u0130kinci paragraf yiyecek ve i\u00E7ecek kal\u0131nt\u0131lar\u0131n\u0131 do\u011Frudan belirtir."},{"Id":3,"Prompt":"Why are possible alternative explanations mentioned?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To show why several observations are needed"},{"Id":"B","Text":"To reject all chemical testing"},{"Id":"C","Text":"To prove every pot was buried deliberately"},{"Id":"D","Text":"To explain why records are unnecessary"}],"Answer":"A","Explanation":"Kal\u0131nt\u0131 ve \u00E7iziklerin farkl\u0131 nedenleri olabilece\u011Fi, tek kan\u0131t\u0131n yetersizli\u011Fini g\u00F6steriyor."},{"Id":4,"Prompt":"The word \u0027these\u0027 in \u0027these relationships\u0027 refers to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Chemical substances"},{"Id":"B","Text":"Improved methods"},{"Id":"C","Text":"Golden ornaments"},{"Id":"D","Text":"Connections between vessels and their surroundings"}],"Answer":"D","Explanation":"\u00D6nceki c\u00FCmle evler ve ortak alanlardaki kaplar\u0131n farkl\u0131 kullan\u0131m ba\u011Flamlar\u0131n\u0131 anlat\u0131yor."},{"Id":5,"Prompt":"Where would this sentence best fit? \u2018Neither kind of evidence offers a complete story on its own.\u2019 Choose a marked location [A]\u2013[D] in the passage.","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Location [A]"},{"Id":"B","Text":"Location [B]"},{"Id":"C","Text":"Location [C]"},{"Id":"D","Text":"Location [D]"}],"Answer":"B","Explanation":"Neither kind iki kan\u0131t t\u00FCr\u00FCne, kimyasal kal\u0131nt\u0131lara ve y\u00FCzey izlerine g\u00F6nderme yapar. [B] bu iki t\u00FCr\u00FCn tan\u0131t\u0131lmas\u0131ndan hemen sonrad\u0131r; sonraki c\u00FCmleler neden tek ba\u015Flar\u0131na kesin sonu\u00E7 vermediklerini a\u00E7\u0131klar."}]'', N''academic-passage'', 3, 2, CONCAT(CAST(N''A broken cooking pot may appear less impressive than a golden ornament, yet it can provide rich evidence about everyday life. Pottery survives in many environments, and even small fragments can preserve traces of how a vessel was made and used. Researchers examine both the material itself and the place where it was discovered.'' AS nvarchar(max)), nchar(10), nchar(10), N''[A] Chemical analysis may reveal residues left by food or drink. Marks on the surface can suggest repeated contact with fire or particular tools. [B] A substance could have entered the pot after it was discarded, while a scratch might have occurred during burial. [C] Researchers therefore compare several independent observations before proposing an explanation.'', nchar(10), nchar(10), N''[D] Location is equally important. Similar vessels found in homes and in communal spaces may have served different purposes. If an object is removed without a record of its surroundings, these relationships can be lost. Careful documentation makes it possible for later researchers to test earlier interpretations using improved methods. Preserving information about an object''''s context can consequently be as valuable as preserving the object itself.''), N''The evidence inside pottery'', 2),
    (''d3200000-0000-4000-8000-000000000004'', N''article'', N''[{"Id":1,"Prompt":"What does the passage explain?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Why all islands have identical habitats"},{"Id":"B","Text":"How isolation and area influence species communities"},{"Id":"C","Text":"Why birds cannot transport seeds"},{"Id":"D","Text":"How farmland increases every population"}],"Answer":"B","Explanation":"Uzakl\u0131k, alan ve kara \u00FCzerindeki habitat par\u00E7alar\u0131 aras\u0131ndaki ba\u011Flant\u0131 ele al\u0131n\u0131yor."},{"Id":2,"Prompt":"Why can small populations be vulnerable?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"They always move too far"},{"Id":"B","Text":"They have too many habitats"},{"Id":"C","Text":"A single event may affect a large part of them"},{"Id":"D","Text":"They cannot use nesting sites"}],"Answer":"C","Explanation":"Tek yuvalama alan\u0131n\u0131n f\u0131rt\u0131nayla yok olmas\u0131 \u00F6rne\u011Fi bu riski g\u00F6steriyor."},{"Id":3,"Prompt":"What does \u0027local disappearances\u0027 mean?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Loss from a particular place"},{"Id":"B","Text":"Extinction across the whole planet"},{"Id":"C","Text":"Seasonal changes in weather"},{"Id":"D","Text":"The formation of new islands"}],"Answer":"A","Explanation":"\u0130kinci paragraf bir adadan kaybolman\u0131n k\u00FCresel yok olu\u015F olmad\u0131\u011F\u0131n\u0131 a\u00E7\u0131klar."},{"Id":4,"Prompt":"Why is a forest surrounded by farms compared to an island?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Both are always surrounded by water"},{"Id":"B","Text":"Both have no birds"},{"Id":"C","Text":"Both contain only one habitat"},{"Id":"D","Text":"The surrounding area may prevent movement"}],"Answer":"D","Explanation":"Tar\u0131m alanlar\u0131n\u0131 ge\u00E7emeyen t\u00FCrler i\u00E7in orman i\u015Flevsel olarak yal\u0131t\u0131lm\u0131\u015Ft\u0131r."},{"Id":5,"Prompt":"What is implied about wildlife corridors?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"They benefit every species equally"},{"Id":"B","Text":"Their usefulness depends on the organism"},{"Id":"C","Text":"They always eliminate local loss"},{"Id":"D","Text":"They are unrelated to movement"}],"Answer":"B","Explanation":"Koridorun yarar\u0131, belirli t\u00FCr\u00FCn nas\u0131l hareket etti\u011Fine ba\u011Fl\u0131d\u0131r."}]'', N''academic-passage'', 4, 2, CONCAT(CAST(N''The number of species on an island reflects a changing balance between arrivals and local disappearances. An island close to a mainland is generally easier for organisms to reach than a distant one. Seeds may travel on wind or birds, while some animals can cross short stretches of water. Distance therefore influences the rate at which new populations become established.'' AS nvarchar(max)), nchar(10), nchar(10), N''Area also matters. Larger islands often contain more types of habitat and can support larger populations. Small populations are more vulnerable to chance events, such as a storm destroying the only nesting site used by a species. A disappearance from one island does not necessarily mean that the species has become extinct everywhere.'', nchar(10), nchar(10), N''These ideas have been applied to habitat fragments on land. A forest surrounded by farms is not literally an island, but species that cannot cross farmland may experience it as one. Creating connections between fragments can make movement easier. Nevertheless, a corridor that benefits one species may not help another. Conservation planning must consider how particular organisms move, rather than assuming that every strip of vegetation provides the same connection.''), N''Why some islands have fewer species'', 2),
    (''d3200000-0000-4000-8000-000000000005'', N''article'', N''[{"Id":1,"Prompt":"What is the passage mainly concerned with?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Using lake sediment to investigate past environments"},{"Id":"B","Text":"Predicting the exact date of future fires"},{"Id":"C","Text":"Removing all sediment from lakes"},{"Id":"D","Text":"Showing that pollen is useless"}],"Answer":"A","Explanation":"Katmanlardaki kan\u0131tlar\u0131n \u00E7evre tarihini anlamada kullan\u0131m\u0131 ve yorum s\u0131n\u0131rlar\u0131 anlat\u0131l\u0131yor."},{"Id":2,"Prompt":"What is generally true of deeper sediment?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"It contains no pollen"},{"Id":"B","Text":"It is always grass"},{"Id":"C","Text":"It is older"},{"Id":"D","Text":"It has no environmental value"}],"Answer":"C","Explanation":"\u0130lk paragraf derindeki malzemenin genellikle daha eski oldu\u011Funu belirtir."},{"Id":3,"Prompt":"Why might an increase in grass pollen be difficult to interpret?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"Grass never produces pollen"},{"Id":"B","Text":"More than one process could explain it"},{"Id":"C","Text":"Trees cannot grow near lakes"},{"Id":"D","Text":"All pollen has the same age"}],"Answer":"B","Explanation":"\u0130klim de\u011Fi\u015Fimi veya insan\u0131n arazi a\u00E7mas\u0131 ayn\u0131 \u00F6r\u00FCnt\u00FCy\u00FC olu\u015Fturabilir."},{"Id":4,"Prompt":"The word \u0027indicator\u0027 is closest in meaning to","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"instruction"},{"Id":"B","Text":"container"},{"Id":"C","Text":"obstacle"},{"Id":"D","Text":"sign"}],"Answer":"D","Explanation":"Ge\u00E7mi\u015F ko\u015Fullar hakk\u0131nda ipucu ya da belirti anlam\u0131nda kullan\u0131l\u0131yor."},{"Id":5,"Prompt":"Why does the author contrast sediment with a precise diary?","Prefix":"","MissingLetters":0,"Options":[{"Id":"A","Text":"To claim scientists should use diaries only"},{"Id":"B","Text":"To emphasize that interpretation involves uncertainty"},{"Id":"C","Text":"To argue that deeper layers are always younger"},{"Id":"D","Text":"To dismiss historical records"}],"Answer":"B","Explanation":"Tarihleme ve neden belirleme belirsiz oldu\u011Fu i\u00E7in katmanlar kesin g\u00FCnl\u00FCk gibi okunamaz."}]'', N''academic-passage'', 5, 2, CONCAT(CAST(N''Material gradually settles on the bottoms of lakes, forming layers of sediment. These layers may contain pollen, mineral particles, and remains of small organisms. By removing a narrow column of sediment, researchers can examine a sequence in which deeper material is generally older than material near the surface. The column acts as a partial record of the surrounding environment.'' AS nvarchar(max)), nchar(10), nchar(10), N''Pollen offers clues about plants that grew nearby. If pollen from trees becomes less common while grass pollen increases, the landscape may have become more open. However, the change could reflect either a shift in climate or human activities such as clearing land. A single indicator rarely identifies the cause with certainty.'', nchar(10), nchar(10), N''Researchers strengthen interpretations by comparing pollen with other evidence, including charcoal particles and historical records. Charcoal may indicate burning, though it does not reveal by itself whether the fire was natural or deliberately started. Establishing the age of each layer also involves uncertainty. Rather than treating sediment as a precise diary, scientists combine several lines of evidence to build and revise explanations of environmental change over time.''), N''A record written in lake sediment'', 2)');
    IF EXISTS (SELECT * FROM [sys].[identity_columns] WHERE [name] IN (N'Id', N'Format', N'ItemsJson', N'Module', N'Position', N'PublicationStatus', N'Text', N'Title', N'Version') AND [object_id] = OBJECT_ID(N'[content].[ReadingSetVersions]'))
        SET IDENTITY_INSERT [content].[ReadingSetVersions] OFF;
END;

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20261006215114_TechnicalManualReadingEdition'
)
BEGIN
    INSERT INTO [__EFMigrationsHistory] ([MigrationId], [ProductVersion])
    VALUES (N'20261006215114_TechnicalManualReadingEdition', N'10.0.12');
